CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(100) PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('administrator','editor') NOT NULL DEFAULT 'editor', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_sessions (id_hash CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES admin_users(id) ON DELETE CASCADE, INDEX(expires_at));
CREATE TABLE IF NOT EXISTS media_assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, storage_key VARCHAR(500) NOT NULL, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, byte_size BIGINT UNSIGNED NOT NULL, alt_text VARCHAR(500) NOT NULL DEFAULT '', credit TEXT, source_url TEXT, illustrative BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(50) NOT NULL, slug VARCHAR(500) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', draft_data JSON NOT NULL, published_data JSON, revision INT UNSIGNED NOT NULL DEFAULT 1, published_at DATETIME, updated_by BIGINT UNSIGNED, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL, INDEX(kind,status));
CREATE TABLE IF NOT EXISTS content_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entry_id BIGINT UNSIGNED NOT NULL, revision INT UNSIGNED NOT NULL, data JSON NOT NULL, author_id BIGINT UNSIGNED, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(entry_id) REFERENCES content_entries(id) ON DELETE CASCADE, FOREIGN KEY(author_id) REFERENCES admin_users(id) ON DELETE SET NULL, UNIQUE(entry_id,revision));
CREATE TABLE IF NOT EXISTS site_settings (setting_key VARCHAR(100) PRIMARY KEY, draft_value JSON NOT NULL, published_value JSON, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS navigation_menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, location VARCHAR(50) NOT NULL UNIQUE, draft_items JSON NOT NULL, published_items JSON, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED, action VARCHAR(100) NOT NULL, entity_type VARCHAR(50), entity_id VARCHAR(100), details JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES admin_users(id) ON DELETE SET NULL);
INSERT IGNORE INTO schema_migrations(version) VALUES ('001_initial_cms');
